  input        W0_en,
  input        W0_clk,
  input  [5:0] W0_data,
  input  [4:0] W1_addr,
  input        W1_en,
  input        W1_clk,
  input  [5:0] W1_data
);
  reg [5:0] Memory[0:26];
  always @(posedge W0_clk) begin
    if (W0_en & 1'h1)
      Memory[W0_addr] <= W0_data;
    if (W1_en & 1'h1)
      Memory[W1_addr] <= W1_data;
  end
  assign R0_data = R0_en ? Memory[R0_addr] : 6'bx;
endmodule
