module rocket_s_tl_arbiter #(
  parameter ADDR_BITS = 64
) (
  input         clock,
  input         reset,
  output        tl_in_0_a_ready,
  input         tl_in_0_a_valid,
  input  [2:0]  tl_in_0_a_bits_opcode,
  input  [2:0]  tl_in_0_a_bits_param,
  input  [2:0]  tl_in_0_a_bits_size,
  input  [3:0]  tl_in_0_a_bits_source,
  input  [ADDR_BITS-1:0] tl_in_0_a_bits_address,
  input  [7:0]  tl_in_0_a_bits_mask,
  input  [63:0] tl_in_0_a_bits_data,
  input         tl_in_0_a_bits_corrupt,
  input         tl_in_0_d_ready,
  output        tl_in_0_d_valid,
  output [2:0]  tl_in_0_d_bits_opcode,
  output [1:0]  tl_in_0_d_bits_param,
  output [2:0]  tl_in_0_d_bits_size,
  output [3:0]  tl_in_0_d_bits_source,
  output        tl_in_0_d_bits_denied,
  output [63:0] tl_in_0_d_bits_data,
  output        tl_in_0_d_bits_corrupt,
  output        tl_in_1_a_ready,
  input         tl_in_1_a_valid,
  input  [2:0]  tl_in_1_a_bits_opcode,
  input  [2:0]  tl_in_1_a_bits_param,
  input  [2:0]  tl_in_1_a_bits_size,
  input  [3:0]  tl_in_1_a_bits_source,
  input  [ADDR_BITS-1:0] tl_in_1_a_bits_address,
  input  [7:0]  tl_in_1_a_bits_mask,
  input  [63:0] tl_in_1_a_bits_data,
  input         tl_in_1_a_bits_corrupt,
  input         tl_in_1_d_ready,
  output        tl_in_1_d_valid,
  output [2:0]  tl_in_1_d_bits_opcode,
  output [1:0]  tl_in_1_d_bits_param,
  output [2:0]  tl_in_1_d_bits_size,
  output [3:0]  tl_in_1_d_bits_source,
  output        tl_in_1_d_bits_denied,
  output [63:0] tl_in_1_d_bits_data,
  output        tl_in_1_d_bits_corrupt,
  input         tl_out_a_ready,
  output        tl_out_a_valid,
  output [2:0]  tl_out_a_bits_opcode,
  output [2:0]  tl_out_a_bits_param,
  output [2:0]  tl_out_a_bits_size,
  output [4:0]  tl_out_a_bits_source,
  output [ADDR_BITS-1:0] tl_out_a_bits_address,
  output [7:0]  tl_out_a_bits_mask,
  output [63:0] tl_out_a_bits_data,
  output        tl_out_a_bits_corrupt,
  output        tl_out_d_ready,
  input         tl_out_d_valid,
  input  [2:0]  tl_out_d_bits_opcode,
  input  [1:0]  tl_out_d_bits_param,
  input  [2:0]  tl_out_d_bits_size,
  input  [4:0]  tl_out_d_bits_source,
  input         tl_out_d_bits_denied,
  input  [63:0] tl_out_d_bits_data,
  input         tl_out_d_bits_corrupt
);
  wire [4:0] _GEN_1 = {{1'd0}, tl_in_0_a_bits_source};
  wire [4:0] in_0_a_bits_source = _GEN_1 | 5'h10;
  wire  requestDOI_0_0 = tl_out_d_bits_source[4];
  wire  requestDOI_0_1 = ~requestDOI_0_0;
  wire [12:0] _beatsAI_decode_T_1 = 13'h3f << tl_in_0_a_bits_size;
  wire [5:0] _beatsAI_decode_T_3 = ~_beatsAI_decode_T_1[5:0];
  wire [2:0] beatsAI_decode = _beatsAI_decode_T_3[5:3];
  wire  beatsAI_opdata = ~tl_in_0_a_bits_opcode[2];
  wire [2:0] beatsAI_0 = beatsAI_opdata ? beatsAI_decode : 3'h0;
  wire [12:0] _beatsAI_decode_T_5 = 13'h3f << tl_in_1_a_bits_size;
  wire [5:0] _beatsAI_decode_T_7 = ~_beatsAI_decode_T_5[5:0];
  wire [2:0] beatsAI_decode_1 = _beatsAI_decode_T_7[5:3];
  wire  beatsAI_opdata_1 = ~tl_in_1_a_bits_opcode[2];
  wire [2:0] beatsAI_1 = beatsAI_opdata_1 ? beatsAI_decode_1 : 3'h0;
  reg [2:0] beatsLeft;
  wire  idle = beatsLeft == 3'h0;
  wire  latch = idle & tl_out_a_ready;
  wire [1:0] readys_valid = {tl_in_1_a_valid,tl_in_0_a_valid};
  wire  _readys_T_3 = ~reset;
  reg [1:0] readys_mask;
  wire [1:0] _readys_filter_T = ~readys_mask;
  wire [1:0] _readys_filter_T_1 = readys_valid & _readys_filter_T;
  wire [3:0] readys_filter = {_readys_filter_T_1,tl_in_1_a_valid,tl_in_0_a_valid};
  wire [3:0] _GEN_2 = {{1'd0}, readys_filter[3:1]};
  wire [3:0] _readys_unready_T_1 = readys_filter | _GEN_2;
  wire [3:0] _readys_unready_T_4 = {readys_mask, 2'h0};
  wire [3:0] _GEN_3 = {{1'd0}, _readys_unready_T_1[3:1]};
  wire [3:0] readys_unready = _GEN_3 | _readys_unready_T_4;
  wire [1:0] _readys_readys_T_2 = readys_unready[3:2] & readys_unready[1:0];
  wire [1:0] readys_readys = ~_readys_readys_T_2;
  wire [1:0] _readys_mask_T = readys_readys & readys_valid;
  wire [2:0] _readys_mask_T_1 = {_readys_mask_T, 1'h0};
  wire [1:0] _readys_mask_T_3 = _readys_mask_T | _readys_mask_T_1[1:0];
  wire  readys_0 = readys_readys[0];
  wire  readys_1 = readys_readys[1];
  wire  earlyWinner_0 = readys_0 & tl_in_0_a_valid;
  wire  earlyWinner_1 = readys_1 & tl_in_1_a_valid;
  wire  _prefixOR_T = earlyWinner_0 | earlyWinner_1;
  wire  _T_10 = tl_in_0_a_valid | tl_in_1_a_valid;
  wire  _T_11 = ~(tl_in_0_a_valid | tl_in_1_a_valid);
  wire [2:0] maskedBeats_0 = earlyWinner_0 ? beatsAI_0 : 3'h0;
  wire [2:0] maskedBeats_1 = earlyWinner_1 ? beatsAI_1 : 3'h0;
  wire [2:0] initBeats = maskedBeats_0 | maskedBeats_1;
  reg  state_0;
  wire  muxStateEarly_0 = idle ? earlyWinner_0 : state_0;
  reg  state_1;
  wire  muxStateEarly_1 = idle ? earlyWinner_1 : state_1;
  wire  _out_0_a_earlyValid_T_3 = state_0 & tl_in_0_a_valid | state_1 & tl_in_1_a_valid;
  wire  out_2_0_a_earlyValid = idle ? _T_10 : _out_0_a_earlyValid_T_3;
  wire  _beatsLeft_T_2 = tl_out_a_ready & out_2_0_a_earlyValid;
  wire [2:0] _GEN_4 = {{2'd0}, _beatsLeft_T_2};
  wire [2:0] _beatsLeft_T_4 = beatsLeft - _GEN_4;
  wire  allowed_0 = idle ? readys_0 : state_0;
  wire  allowed_1 = idle ? readys_1 : state_1;
  wire [63:0] _T_27 = muxStateEarly_0 ? tl_in_0_a_bits_data : 64'h0;
  wire [63:0] _T_28 = muxStateEarly_1 ? tl_in_1_a_bits_data : 64'h0;
  wire [7:0] _T_30 = muxStateEarly_0 ? tl_in_0_a_bits_mask : 8'h0;
  wire [7:0] _T_31 = muxStateEarly_1 ? tl_in_1_a_bits_mask : 8'h0;
  wire [ADDR_BITS-1:0] _T_33 = muxStateEarly_0 ? tl_in_0_a_bits_address : 0;
  wire [ADDR_BITS-1:0] _T_34 = muxStateEarly_1 ? tl_in_1_a_bits_address : 0;
  wire [4:0] _T_36 = muxStateEarly_0 ? in_0_a_bits_source : 5'h0;
  wire [4:0] in_1_a_bits_source = {{1'd0}, tl_in_1_a_bits_source};
  wire [4:0] _T_37 = muxStateEarly_1 ? in_1_a_bits_source : 5'h0;
  wire [2:0] _T_39 = muxStateEarly_0 ? tl_in_0_a_bits_size : 3'h0;
  wire [2:0] _T_40 = muxStateEarly_1 ? tl_in_1_a_bits_size : 3'h0;
  wire [2:0] _T_42 = muxStateEarly_0 ? tl_in_0_a_bits_param : 3'h0;
  wire [2:0] _T_43 = muxStateEarly_1 ? tl_in_1_a_bits_param : 3'h0;
  wire [2:0] _T_45 = muxStateEarly_0 ? tl_in_0_a_bits_opcode : 3'h0;
  wire [2:0] _T_46 = muxStateEarly_1 ? tl_in_1_a_bits_opcode : 3'h0;
  assign tl_in_1_a_ready = tl_out_a_ready & allowed_1;
  assign tl_in_1_d_valid = tl_out_d_valid & requestDOI_0_1;
  assign tl_in_1_d_bits_opcode = tl_out_d_bits_opcode;
  assign tl_in_1_d_bits_param = tl_out_d_bits_param;
  assign tl_in_1_d_bits_size = tl_out_d_bits_size;
  assign tl_in_1_d_bits_source = tl_out_d_bits_source[3:0];
  assign tl_in_1_d_bits_denied = tl_out_d_bits_denied;
  assign tl_in_1_d_bits_data = tl_out_d_bits_data;
  assign tl_in_1_d_bits_corrupt = tl_out_d_bits_corrupt;
  assign tl_in_0_a_ready = tl_out_a_ready & allowed_0;
  assign tl_in_0_d_valid = tl_out_d_valid & requestDOI_0_0;
  assign tl_in_0_d_bits_opcode = tl_out_d_bits_opcode;
  assign tl_in_0_d_bits_param = tl_out_d_bits_param;
  assign tl_in_0_d_bits_size = tl_out_d_bits_size;
  assign tl_in_0_d_bits_source = tl_out_d_bits_source[3:0];
  assign tl_in_0_d_bits_denied = tl_out_d_bits_denied;
  assign tl_in_0_d_bits_data = tl_out_d_bits_data;
  assign tl_in_0_d_bits_corrupt = tl_out_d_bits_corrupt;
  assign tl_out_a_valid = idle ? _T_10 : _out_0_a_earlyValid_T_3;
  assign tl_out_a_bits_opcode = _T_45 | _T_46;
  assign tl_out_a_bits_param = _T_42 | _T_43;
  assign tl_out_a_bits_size = _T_39 | _T_40;
  assign tl_out_a_bits_source = _T_36 | _T_37;
  assign tl_out_a_bits_address = _T_33 | _T_34;
  assign tl_out_a_bits_mask = _T_30 | _T_31;
  assign tl_out_a_bits_data = _T_27 | _T_28;
  assign tl_out_a_bits_corrupt = muxStateEarly_0 & tl_in_0_a_bits_corrupt | muxStateEarly_1 &
    tl_in_1_a_bits_corrupt;
  assign tl_out_d_ready = requestDOI_0_0 & tl_in_0_d_ready | requestDOI_0_1 & tl_in_1_d_ready;
  always @(posedge clock) begin
    if (reset) begin
      beatsLeft <= 3'h0;
    end else if (latch) begin
      beatsLeft <= initBeats;
    end else begin
      beatsLeft <= _beatsLeft_T_4;
    end
    if (reset) begin
      readys_mask <= 2'h3;
    end else if (latch & |readys_valid) begin
      readys_mask <= _readys_mask_T_3;
    end
    if (reset) begin
      state_0 <= 1'h0;
    end else if (idle) begin
      state_0 <= earlyWinner_0;
    end
    if (reset) begin
      state_1 <= 1'h0;
    end else if (idle) begin
      state_1 <= earlyWinner_1;
    end
  end
endmodule
module rocket_s_TLROM(
  output        auto_in_a_ready,
  input         auto_in_a_valid,
  input  [1:0]  auto_in_a_bits_size,
input  [7:0]  auto_in_a_bits_source,
  output [7:0]  auto_in_d_bits_source,
  input  [16:0] auto_in_a_bits_address,
  input         auto_in_d_ready,
  output        auto_in_d_valid,
  output [1:0]  auto_in_d_bits_size,
  output [63:0] auto_in_d_bits_data
);
  wire [8:0] index = auto_in_a_bits_address[11:3];
  wire [3:0] high = auto_in_a_bits_address[15:12];
  wire [63:0] dout;
  riscv_bootrom bootrom (
    .addr(index),
    .dout(dout)
  );
  assign auto_in_a_ready = auto_in_d_ready;
  assign auto_in_d_valid = auto_in_a_valid;
  assign auto_in_d_bits_size = auto_in_a_bits_size;
  assign auto_in_d_bits_source = auto_in_a_bits_source;
  assign auto_in_d_bits_data = |high ? 64'h0 : dout;
endmodule
